    technologies: ["rejuv-ayac-diagnostic-delay", "rejuv-ayac-education-and-work", "rejuv-ayac-services", "fertility-preservation", "survivorship-care-plan"],
    terms: ["late-effects", "quality-of-life"], bottlenecks: ["b-survivorship", "b-rare-cancers", "b-care-fragmentation"],
    related: ["teenage-cancer-trust", "journal-of-adolescent-and-young-adult-oncology", "idea-acc-aya-survivorship-passport"],
